from collections import deque, defaultdict
R,C=len(grid),len(grid[0]); seen=set(); comps=[]
for r in range(R):
    for c in range(C):
        val=grid[r][c]
        if val==8 or (r,c) in seen: continue
        q=deque([(r,c)]); seen.add((r,c)); cells=[]
        while q:
            y,x=q.popleft(); cells.append((y,x))
            for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                ny,nx=y+dy,x+dx
                if 0<=ny<R and 0<=nx<C and (ny,nx) not in seen and grid[ny][nx]==val:
                    seen.add((ny,nx)); q.append((ny,nx))
        comps.append((val,len(cells),(min(y for y,x in cells),min(x for y,x in cells),max(y for y,x in cells),max(x for y,x in cells))))
print(comps)

out=[row[:] for row in grid]
for r,color,n in [(3,2,2),(9,4,4),(15,3,1),(21,1,1)]:
    for c in range(11-2*n,10,2):
        assert out[r][c]==8, (r,c,out[r][c])
        out[r][c]=color
print('\n'.join(' '.join(map(str,row)) for row in out))

# Remove every non-frame object; preserve only the four large rectangular frames.
clean=[row[:] for row in grid]
for val,size,bbox in comps:
    if size == 28:  # the four 5x11 hollow frame borders
        continue
    y0,x0,y1,x1=bbox
    # Erase cells belonging to this same-color component, bounded by its bbox.
    for y in range(y0,y1+1):
        for x in range(x0,x1+1):
            if clean[y][x] == val:
                clean[y][x] = 8
# Use the count of removed components of each border color.
counts={2:2,4:4,3:1,1:1}
for r,color,n in [(3,2,counts[2]),(9,4,counts[4]),(15,3,counts[3]),(21,1,counts[1])]:
    for c in range(11-2*n,10,2):
        assert clean[r][c] == 8
        clean[r][c]=color
print('\n'.join(' '.join(map(str,row)) for row in clean))
